function sumEven(numbers) {
  let sum = 0;
  for (let i = 0; i < numbers.length; i++) {
    const num = numbers[i];
    if (typeof num === 'number' && Number.isInteger(num) && num % 2 === 0) {
      sum += num;
    }
  }
  return sum;
}
