function wordCount(text) {
    const counts = {};
    const words = text.toLowerCase().match(/[a-z]+/g);

    if (!words) {
        return counts;
    }

    for (let i = 0; i < words.length; i++) {
        const word = words[i];
        counts[word] = (counts[word] || 0) + 1;
    }

    return counts;
}
